@Named("formatMembershipLevel")
default Integer formatMembershipLevel(Owner owner) {
    if (owner == null) {
        return null;
    }
    int level = 1;
    boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
    if (hasEmail) {
        level++;
